-- Galeries AFROBACK : mythes, archives réelles (2026-10-16)
-- Source : galeries-mythes_2026-10-15.json (agent iconographe), 28 images Wikimedia Commons vérifiées une à une par Jarvis.
-- Prérequis : app-mobile/mobile-app/supabase/schema-galerie.sql déjà exécuté.
-- Les illustrations (ordres manquants) seront ajoutées après génération. Idempotent : remplace les archives de ces 5 mythes.

begin;

delete from public.galerie_images where type_contenu = 'mythe' and nature = 'archive'
  and slug in ('mythe-miengu-esprits-eau-sawa', 'mythe-nchare-yen-bamoun', 'mythe-ngan-medza-beti', 'mythe-ngog-lituba-bassa', 'mythe-sao-geants-kotoko');


commit;

select slug, count(*) from public.galerie_images where type_contenu = 'mythe' group by slug order by slug;
